+        assertTrue(NonSubscribedFeedsCleaner.shouldDelete(feed));
+
+        feed.setLastRefreshAttempt(System.currentTimeMillis() + TimeUnit.MILLISECONDS.convert(200, TimeUnit.DAYS));
